package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := num(), int(num())
	mem, ids := make([]int64, n), make([]int64, n) // ids[j]: allocation owning unit j, 0 for none
	for j := range mem {
		mem[j] = num()
	}
	nextID := int64(1)
	out := []byte{}
	for k := 0; k < q; k++ {
		typ, x := num(), num()
		var res int64
		if typ == 0 {
			res = -1
			// Candidate starts are multiples of 8; take the leftmost fully free block.
			for s := int64(0); s < n && res < 0; s += 8 {
				if s+x > n {
					continue
				}
				ok := true
				for j := s; j < s+x && ok; j++ {
					ok = mem[j] == 0
				}
				if ok {
					res = s
				}
			}
			if res >= 0 {
				for j := res; j < res+x; j++ {
					mem[j], ids[j] = 1, nextID
				}
				nextID++
			}
		} else {
			var freed int64
			for j := range ids {
				if ids[j] == x {
					ids[j], mem[j] = 0, 0
					freed++
				}
			}
			res = -1
			if freed > 0 {
				res = freed
			}
		}
		if k > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, res, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
